"""Assemble and verify wheel and C++ assets for PR downloads and releases."""

import argparse
import fnmatch
import gzip
import hashlib
import io
from pathlib import Path
import re
import shutil
import struct
import tarfile


COMPONENTS = {"streamer": "libstreamer.so", "s3": "libstreamers3.so",
              "gcs": "libstreamergcs.so", "azure": "libstreamerazure.so"}
ARCHITECTURES = {"x86_64": 62, "aarch64": 183}  # ELF e_machine values
HEADERS = {"streamer.h", "device.h", "response_code.h", "submission_id.h"}
# The third-party notice of the four libraries in the SDK (generated by third_party_notices/generate.py).
NOTICE_NAME = "THIRD_PARTY_NOTICES.txt"
REPOSITORY = Path(__file__).resolve().parents[2]
SDK_EXTRAS = {
    "lib/pkgconfig/runai-streamer.pc": "cpp/sdk/runai-streamer.pc.in",
    "lib/cmake/runai-streamer/runai-streamer-config.cmake": "cpp/sdk/runai-streamer-config.cmake",
    **{f"examples/hello_streamer/{name}": f"examples/hello_streamer/{name}"
       for name in ("main.c", "CMakeLists.txt", "README.md")},
}


def require(condition, message):
    if not condition:
        raise ValueError(message)


def checksum(path):
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def regular_files(directory):
    """Reject links and special files instead of silently dereferencing or skipping them."""
    require(directory.is_dir() and not directory.is_symlink(), f"Missing directory: {directory}")
    files = {}
    for path in sorted(directory.rglob("*")):
        require(not path.is_symlink(), f"Unexpected symlink: {path}")
        if path.is_dir():
            continue
        require(path.is_file(), f"Not a regular file: {path}")
        files[path.relative_to(directory).as_posix()] = path
    return files


def select_wheels(files, version):
    files = list(files)
    selected = []
    for component in COMPONENTS:
        package = "runai_model_streamer" + ("" if component == "streamer" else "_" + component)
        for arch in ARCHITECTURES:
            pattern = f"{package}-{version}-py3-none-*_{arch}.whl"
            matches = [path for path in files if fnmatch.fnmatchcase(path.name, pattern)]
            require(len(matches) == 1, f"Expected one {package} wheel for {arch} at version {version}")
            selected.append(matches[0])
    return selected


def sdk_name(version, arch):
    return f"runai-model-streamer-cpp-sdk-{version}-linux-{arch}"


def sdk_inputs(artifacts, notices):
    """Validate component artifacts and return SDK files grouped by architecture."""
    require(notices.is_file() and not notices.is_symlink(), f"Missing third-party notices: {notices}")
    shared_hashes = None
    sdks = {}
    for arch, machine in ARCHITECTURES.items():
        sdk = {}
        for component, library in COMPONENTS.items():
            directory = artifacts / f"ci-cpp-{component}-{arch}"
            files = regular_files(directory)
            shared = {name: path for name, path in files.items()
                      if name == "LICENSE" or name.startswith("include/streamer/")}
            required = {"LICENSE"} | {f"include/streamer/{header}" for header in HEADERS}
            require(required <= shared.keys(), f"Missing public headers or LICENSE in {directory}")
            hashes = {name: checksum(path) for name, path in shared.items()}
            if shared_hashes is None:
                shared_hashes = hashes
            require(hashes == shared_hashes, f"Headers or LICENSE differ in {directory}")
            name = f"lib/{library}"
            require(name in files, f"Missing {name} in {directory}")
            with files[name].open("rb") as stream:
                header = stream.read(64)
            require(len(header) == 64 and header[:6] == b"\x7fELF\x02\x01"
                    and struct.unpack_from("<HH", header, 16) == (3, machine),
                    f"Expected a 64-bit little-endian {arch} ELF shared library: {files[name]}")
            sdk.update(shared)
            sdk[name] = files[name]
        sdk[NOTICE_NAME] = notices
        sdks[arch] = sdk
    return sdks


def write_sdk(destination, root, files):
    # Fixed timestamps and metadata keep repackaging the same input reproducible.
    directories = {root}
    for name in files:
        directories.update(str(parent) for parent in (Path(root) / name).parents if str(parent) != ".")
    with destination.open("xb") as raw, gzip.GzipFile(filename="", mode="wb", fileobj=raw, mtime=0) as gz:
        with tarfile.open(fileobj=gz, mode="w", format=tarfile.PAX_FORMAT) as archive:
            for name in sorted(directories | {f"{root}/{name}" for name in files}):
                info = tarfile.TarInfo(name)
                if name in directories:
                    info.type = tarfile.DIRTYPE
                    info.mode = 0o755
                    archive.addfile(info)
                else:
                    value = files[name[len(root) + 1:]]
                    info.mode = 0o644
                    if isinstance(value, bytes):
                        info.size = len(value)
                        archive.addfile(info, io.BytesIO(value))
                    else:
                        info.size = value.stat().st_size
                        with value.open("rb") as stream:
                            archive.addfile(info, stream)


def create_bundle(wheels, cpp, bundle, version, notices):
    wheel_paths = select_wheels(regular_files(wheels).values(), version)
    sdks = sdk_inputs(cpp, notices)
    # A fresh output directory prevents leftover assets from entering a release.
    bundle.mkdir(parents=True, exist_ok=False)
    (bundle / "wheels").mkdir()
    (bundle / "cpp").mkdir()
    assets = []
    for path in wheel_paths:
        destination = bundle / "wheels" / path.name
        shutil.copyfile(path, destination)
        assets.append(destination)
    for arch, files in sdks.items():
        for name, source in SDK_EXTRAS.items():
            data = (REPOSITORY / source).read_bytes()
            if name.endswith(".pc"):
                data = data.replace(b"@VERSION@", version.encode("utf-8"))
            files[name] = data
        name = sdk_name(version, arch)
        destination = bundle / "cpp" / f"{name}.tar.gz"
        write_sdk(destination, name, files)
        assets.append(destination)
    (bundle / "SHA256SUMS").write_text("".join(
        f"{checksum(path)}  {path.name}\n" for path in sorted(assets, key=lambda path: path.name)),
        encoding="utf-8")
    verify_bundle(bundle, version)


def verify_bundle(bundle, version):
    files = regular_files(bundle)
    wheel_paths = select_wheels((bundle / "wheels").glob("*.whl"), version)
    assets = {path.name: path for path in wheel_paths}
    assets.update({f"{sdk_name(version, arch)}.tar.gz": bundle / "cpp" / f"{sdk_name(version, arch)}.tar.gz"
                   for arch in ARCHITECTURES})
    expected = {path.relative_to(bundle).as_posix() for path in assets.values()} | {"SHA256SUMS"}
    require(set(files) == expected, "Release bundle must contain exactly eight wheels, two SDKs, and SHA256SUMS")
    lines = files["SHA256SUMS"].read_text(encoding="utf-8").splitlines()
    require(len(lines) == len(assets), "Checksum manifest must contain all ten assets exactly once")
    seen = set()
    for line in lines:
        match = re.fullmatch(r"([0-9a-f]{64})  ([^/\\]+)", line)
        require(match is not None, f"Invalid checksum entry: {line}")
        digest, name = match.groups()
        require(name in assets and name not in seen, f"Unexpected or duplicate checksum entry: {name}")
        require(checksum(assets[name]) == digest, f"Checksum mismatch: {name}")
        seen.add(name)
    for arch in ARCHITECTURES:
        name = sdk_name(version, arch)
        with tarfile.open(bundle / "cpp" / f"{name}.tar.gz") as archive:
            members = {member.name: member for member in archive.getmembers()}
        for required in ("LICENSE", NOTICE_NAME, *SDK_EXTRAS):
            member = members.get(f"{name}/{required}")
            require(member is not None and member.isfile() and member.size > 0,
                    f"{name}.tar.gz does not contain a regular, non-empty {required}")


def main():
    """Parse CLI options and create or verify a bundle with an allowed version."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("command", choices=("create", "verify"))
    parser.add_argument("--version", required=True)
    parser.add_argument("--allow-development-version", action="store_true",
                        help="also accept PR versions of the form 0.0.0+dev.<7-character SHA>")
    parser.add_argument("--bundle", type=Path, default=Path("release-bundle"))
    parser.add_argument("--wheels", type=Path, default=Path("packages"))
    parser.add_argument("--cpp", type=Path, default=Path("cpp-artifacts"))
    parser.add_argument("--notices", type=Path, default=Path("third_party_notices/sdk.txt"),
                        help="third-party notice added to each SDK archive")
    args = parser.parse_args()
    try:
        development_version = args.allow_development_version and re.fullmatch(
            r"0\.0\.0\+dev\.[0-9a-f]{7}", args.version)
        require(development_version or re.fullmatch(
                    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)", args.version),
                "Release version must have the form X.Y.Z")
        if args.command == "create":
            create_bundle(args.wheels, args.cpp, args.bundle, args.version, args.notices)
        else:
            verify_bundle(args.bundle, args.version)
    except (OSError, ValueError) as error:
        parser.exit(1, f"Release bundle error: {error}\n")


if __name__ == "__main__":
    main()
